// Generates the CSS for each primitive folder from its .tokens.json, and the color values in
// brand-assets/patterns/tokens/placeholder.tokens.json. The .tokens.json files are the source of
// truth: never edit the generated files by hand.
//
//   node primitives/build.mjs           write every generated file
//   node primitives/build.mjs --check   fail (exit 1) if a generated file is out of date
//
// No dependencies. Typography is not generated: typography.css also holds the creative classes,
// so it is kept in step with typography.tokens.json by hand.

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const CHECK = process.argv.includes("--check");
const read = (rel) => JSON.parse(readFileSync(join(ROOT, rel), "utf8"));

const SOURCES = {
  colors: "primitives/colors/colors.tokens.json",
  spacing: "primitives/spacing/spacing.tokens.json",
  radius: "primitives/radius/radius.tokens.json",
  borderWidth: "primitives/border-width/border-width.tokens.json",
  breakpoints: "primitives/breakpoints/breakpoints.tokens.json",
  elevation: "primitives/elevation/elevation.tokens.json",
};
const docs = Object.fromEntries(Object.entries(SOURCES).map(([key, rel]) => [key, read(rel)]));

// One namespace for aliases, so {color.neutral.950} resolves from any file.
const all = {};
for (const doc of Object.values(docs)) {
  for (const [key, value] of Object.entries(doc)) {
    if (key.startsWith("$")) continue;
    if (key in all) throw new Error(`Token group "${key}" is defined in two files`);
    all[key] = value;
  }
}

const isToken = (node) => node && typeof node === "object" && "$value" in node;
const get = (path) => path.split(".").reduce((node, key) => node?.[key], all);

function resolve(value, seen = []) {
  if (typeof value === "string" && /^\{.+\}$/.test(value)) {
    const path = value.slice(1, -1);
    if (seen.includes(path)) throw new Error(`Alias loop: ${[...seen, path].join(" -> ")}`);
    const token = get(path);
    if (!isToken(token)) throw new Error(`Unknown token ${value}`);
    return resolve(token.$value, [...seen, path]);
  }
  return value;
}

// The primitive a role points to, for a short comment in the CSS, for example "neutral-950".
const aliasName = (value) => (typeof value === "string" && /^\{color\.(.+)\}$/.test(value) ? value.slice(7, -1).replace(/\./g, "-") : null);

function hex(value) {
  const v = resolve(value);
  if (typeof v === "string" && /^#[0-9a-f]{6}$/i.test(v)) return v.toUpperCase();
  if (v && typeof v.hex === "string") return v.hex.toUpperCase();
  throw new Error(`Not a color: ${JSON.stringify(value)}`);
}

function dimension(value) {
  const v = resolve(value);
  if (typeof v === "string" || typeof v === "number") return String(v);
  if (v && "value" in v) return `${v.value}${v.unit ?? ""}`;
  throw new Error(`Not a dimension: ${JSON.stringify(value)}`);
}

function* leaves(node, path = []) {
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith("$")) continue;
    if (isToken(child)) yield [[...path, key], child];
    else if (child && typeof child === "object") yield* leaves(child, [...path, key]);
  }
}

const rgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16)).join(" ");
const pct = (n) => `${+(n * 100).toFixed(2)}%`;
function gradient(token) {
  const angle = token.$extensions?.qdrant?.angle ?? 180;
  const stops = token.$value;
  const plainEnds = stops.length === 2 && stops[0].position === 0 && stops[1].position === 1;
  const parts = stops.map((stop) => {
    const color = stop.opacity === undefined ? hex(stop.color) : `rgb(${rgb(hex(stop.color))} / ${stop.opacity})`;
    return plainEnds ? color : `${color} ${pct(stop.position)}`;
  });
  const names = stops.map((stop) => aliasName(stop.color)).filter(Boolean);
  return { value: `linear-gradient(${angle}deg, ${parts.join(", ")})`, note: names.join(" → ") };
}

const header = (source) => `/* Generated by primitives/build.mjs from ${source}. Do not edit by hand: change the JSON and run the script. */`;
const line = (name, value, note) => `  ${name}: ${value};${note ? ` /* ${note} */` : ""}`;

const outputs = {};

// colors.css: primitives (no deprecated steps), brand names, asset colors, roles, gradients, light theme.
{
  const c = docs.colors;
  const out = [header("colors.tokens.json"), ":root {", "  /* Primitives (Figma). Deprecated MUI accent steps (a100 to a700) stay in the JSON only. */"];
  for (const [family, steps] of Object.entries(c.color)) {
    if (family.startsWith("$")) continue;
    for (const [[step], token] of leaves(steps)) {
      if (token.$deprecated) continue;
      out.push(line(`--qd-color-${family}-${step}`, hex(token.$value)));
    }
  }
  out.push("", "  /* Brand names (aliases) */");
  for (const [[name], token] of leaves(c.brand)) out.push(line(`--qd-color-brand-${name}`, hex(token.$value), aliasName(token.$value)));
  for (const [[name], token] of leaves(c.asset)) out.push(line(`--qd-color-${name}`, hex(token.$value)));
  out.push("", "  /* Roles: dark theme, the default */");
  for (const [path, token] of leaves(c.semantic.color)) out.push(line(`--qd-color-${path.join("-")}`, hex(token.$value), aliasName(token.$value)));
  out.push("");
  for (const [[name], token] of leaves(c.gradient)) {
    const g = gradient(token);
    out.push(line(`--qd-gradient-${name}`, g.value, g.note));
  }
  out.push("}", "", "/* Light theme. Accent colors stay the same in both themes. */", '[data-theme="light"] {');
  for (const [path, token] of leaves(c.theme.light.color)) out.push(line(`--qd-color-${path.join("-")}`, hex(token.$value), aliasName(token.$value)));
  out.push("}", "");
  outputs["primitives/colors/colors.css"] = out.join("\n");
}

// Plain dimension folders: one :root block each.
function dimensionCss(source, groups) {
  const out = [header(source), ":root {"];
  groups.forEach(([group, prefix, comment], i) => {
    if (i) out.push("");
    if (comment) out.push(`  /* ${comment} */`);
    for (const [path, token] of leaves(group)) out.push(line(`${prefix}-${path.join("-")}`, dimension(token.$value)));
  });
  out.push("}", "");
  return out.join("\n");
}
outputs["primitives/spacing/spacing.css"] = dimensionCss("spacing.tokens.json", [
  [docs.spacing.spacing, "--qd-spacing", "4px grid: only these values"],
  [docs.spacing.layout, "--qd-layout", "Web page layout, designed at a 1440px viewport"],
]);
outputs["primitives/radius/radius.css"] = dimensionCss("radius.tokens.json", [[docs.radius.radius, "--qd-radius"]]);
outputs["primitives/border-width/border-width.css"] = dimensionCss("border-width.tokens.json", [[docs.borderWidth["border-width"], "--qd-border-width"]]);
outputs["primitives/breakpoints/breakpoints.css"] = dimensionCss("breakpoints.tokens.json", [
  [docs.breakpoints.breakpoint, "--qd-breakpoint", "Minimum widths. CSS variables can't be used inside @media: use the px values there"],
]);

// elevation.css: dark on :root (this repo's default theme), light on [data-theme="light"].
{
  const p = docs.elevation["paper-elevation"];
  const block = (set) => [...leaves(set)].map(([[level], token]) => line(`--qd-paper-elevation-${level}`, hex(token.$value), aliasName(token.$value)));
  outputs["primitives/elevation/elevation.css"] = [
    header("elevation.tokens.json"),
    "/* Product only (Qdrant Cloud on MUI). Creatives and marketing use the background roles in colors.css. */",
    ":root {", ...block(p.dark), "}", "", '[data-theme="light"] {', ...block(p.light), "}", "",
  ].join("\n");
}

// Patterns keep their own token names (Design Lab and its stored meshes use them). Each token says
// which primitive it takes its value from in $extensions.qdrant.from; this fills in the value.
{
  const rel = "brand-assets/patterns/tokens/placeholder.tokens.json";
  const tokens = read(rel);
  for (const [path, token] of leaves(tokens.color)) {
    const from = token.$extensions?.qdrant?.from;
    if (!from) throw new Error(`${rel}: color.${path.join(".")} has no $extensions.qdrant.from`);
    token.$value = hex(`{${from}}`);
  }
  outputs[rel] = JSON.stringify(tokens, null, 2) + "\n";
}

let stale = 0;
for (const [rel, text] of Object.entries(outputs)) {
  const path = join(ROOT, rel);
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === text) continue;
  if (CHECK) { console.error(`Out of date: ${rel}`); stale++; continue; }
  writeFileSync(path, text);
  console.log(`Wrote ${rel}`);
}
if (CHECK && stale) { console.error("Run: node primitives/build.mjs"); process.exit(1); }
if (CHECK) console.log("All generated files are up to date.");
